/**
 * @summary Get the current show configuration
 */
export const getGetShowUrl = () => {
  return `/api/show`;
};

export const getShow = async (options?: RequestInit): Promise<ShowConfig> => {
  return customFetch<ShowConfig>(getGetShowUrl(), {
    ...options,
    method: "GET",
  });
};

export const getGetShowQueryKey = () => {
  return [`/api/show`] as const;
};

export const getGetShowQueryOptions = <
  TData = Awaited<ReturnType<typeof getShow>>,
  TError = ErrorType<unknown>,
>(options?: {
  query?: UseQueryOptions<Awaited<ReturnType<typeof getShow>>, TError, TData>;
  request?: SecondParameter<typeof customFetch>;
}) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey = queryOptions?.queryKey ?? getGetShowQueryKey();

  const queryFn: QueryFunction<Awaited<ReturnType<typeof getShow>>> = ({
    signal,
  }) => getShow({ signal, ...requestOptions });

  return { queryKey, queryFn, ...queryOptions } as UseQueryOptions<
    Awaited<ReturnType<typeof getShow>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

export type GetShowQueryResult = NonNullable<
  Awaited<ReturnType<typeof getShow>>
>;
export type GetShowQueryError = ErrorType<unknown>;

/**
 * @summary Get the current show configuration
 */

export function useGetShow<
  TData = Awaited<ReturnType<typeof getShow>>,
  TError = ErrorType<unknown>,
>(options?: {
  query?: UseQueryOptions<Awaited<ReturnType<typeof getShow>>, TError, TData>;
  request?: SecondParameter<typeof customFetch>;
}): UseQueryResult<TData, TError> & { queryKey: QueryKey } {
  const queryOptions = getGetShowQueryOptions(options);

  const query = useQuery(queryOptions) as UseQueryResult<TData, TError> & {
    queryKey: QueryKey;
  };

  return { ...query, queryKey: queryOptions.queryKey };
}

